<template><NuxtLayout><h1>Visual Rack Designer</h1><p class="muted">Create sites and racks. Drag inventory devices into free rack units, or use the placement controls.</p><div class="panel"><h2>Sites and racks</h2><div class="fields"><label>Company<select v-model.number="newSiteCompany"><option :value="0">Choose company</option><option v-for="c in companies" :key="c.id" :value="Number(c.id)">{{c.name}}</option></select></label><label>New site<input v-model="siteName" placeholder="Kildare Campus"></label><div style="align-self:end"><button :disabled="!editable" @click="addSite">Add site</button></div><label>Site<select v-model.number="rackForm.site_id"><option :value="0">Choose site</option><option v-for="s in sites" :key="s.id" :value="s.id">{{s.name}}</option></select></label><label>Rack name<input v-model="rackForm.name" placeholder="Comms Rack A"></label><label>Height (U)<input v-model.number="rackForm.height_u" type="number" min="1" max="60"></label><label>Location<input v-model="rackForm.location" placeholder="Building / room"></label><div style="align-self:end"><button :disabled="!editable" @click="addRack">Add rack</button></div></div><p v-if="error" class="error">{{error}}</p></div><div class="split"><section class="panel"><h2>Rack elevation</h2><p v-if="error" class="error" role="alert">{{error}}</p><label>Selected rack<select v-model="selectedRack"><option :value="0">Choose rack</option><option v-for="r in racks" :key="r.id" :value="Number(r.id)">{{r.site_name}} — {{r.name}} ({{r.height_u}}U)</option></select></label><p class="muted">Drop an unplaced device on a free unit. Devices occupy their configured rack height.</p><div v-if="rack" class="rack"><div v-for="slot in rackSlots" :key="slot.u" class="rack-row" @dragover="allowDrop($event)" @drop="dropOn($event, slot.u)"><span class="rack-u">{{slot.u}}U</span><div v-if="slot.device && slot.top" class="rack-slot rack-device" :class="slot.device.device_type" draggable="true" @dragstart="startDrag($event, slot.device.id)" @dragend="dragId=0" :style="{height:(slot.device.rack_height*38-4)+'px',position:'relative',zIndex:2,alignSelf:'flex-start'}"><strong>{{slot.device.name}}</strong><span>{{slot.device.device_type}}</span></div><div v-else-if="slot.device" class="rack-slot" style="visibility:hidden"></div><div v-else class="rack-slot">Available</div></div></div><p v-if="!rack" class="muted">Select a rack to display its numbered rack units.</p></section><section class="panel"><h2>Device placement</h2><p class="muted">Drag an unplaced device from this list to the rack, or select its starting U position.</p><div v-for="d in devices.filter(x=>x.rack_id==null)" :key="d.id" class="panel" draggable="true" @dragstart="startDrag($event, d.id)" @dragend="dragId=0"><strong>{{d.name}}</strong> <span class="pill">{{d.rack_height}}U</span><div class="fields"><label>Starting U<input :id="'pos-'+d.id" type="number" min="1" :max="rack?.height_u||60" value="1"></label><div style="align-self:end"><button :disabled="!editable||!rack" @click="place(d)">Place</button></div></div></div><p v-if="!devices.some(x=>x.rack_id==null)" class="muted">No unplaced devices. Add equipment in Device Inventory.</p><h2>Installed equipment</h2><div v-for="d in devices.filter(x=>Number(x.rack_id)===Number(selectedRack))" :key="d.id" style="padding:8px;border-bottom:1px solid #2b4058">{{d.name}} · U{{d.rack_u}} · {{d.rack_height}}U <button :disabled="!editable" style="float:right" @click="unplace(d)">Remove</button></div></section></div></NuxtLayout></template><script setup lang="ts">const {data:companies}=await useFetch<any[]>('/api/companies',{default:()=>[]});const newSiteCompany=ref(0);const auth=useAuth(),editable=computed(()=>['admin','editor'].includes(auth.value?.role));const {data:sites,refresh:refreshSites}=await useFetch<any[]>('/api/sites',{default:()=>[]});const {data:racks,refresh:refreshRacks}=await useFetch<any[]>('/api/racks',{default:()=>[]});const {data:devices,refresh:refreshDevices}=await useFetch<any[]>('/api/devices',{default:()=>[]});const siteName=ref(''),rackForm=reactive({site_id:0,name:'',height_u:42,location:''}),selectedRack=ref(0),dragId=ref(0),error=ref('');watch(racks,(items)=>{if(items.length&&!items.some(r=>Number(r.id)===Number(selectedRack.value)))selectedRack.value=Number(items[0].id)},{immediate:true});const rack=computed(()=>racks.value.find(x=>Number(x.id)===Number(selectedRack.value)));const rackSlots=computed(()=>{if(!rack.value)return [];const slots=[];for(let u=Number(rack.value.height_u);u>=1;u--){const d=devices.value.find(x=>Number(x.rack_id)===Number(selectedRack.value)&&x.rack_u!==null&&x.rack_u<=u&&x.rack_u+x.rack_height-1>=u);slots.push({u,device:d,top:!!d&&Number(d.rack_u)+Number(d.rack_height)-1===u})}return slots});async function run(fn:()=>Promise<any>){error.value='';try{await fn()}catch(e:any){error.value=e?.data?.statusMessage||e?.message||'Operation failed'}}async function addSite(){await run(async()=>{await $fetch('/api/sites',{method:'POST',body:{name:siteName.value,company_id:newSiteCompany.value}});siteName.value='';await refreshSites()})}async function addRack(){await run(async()=>{await $fetch('/api/racks',{method:'POST',body:rackForm});rackForm.name='';await refreshRacks()})}async function move(id:number,rack_id:number|null,rack_u:number|null){await run(async()=>{await $fetch(`/api/devices/${id}`,{method:'PATCH',body:{rack_id,rack_u}});await refreshDevices()})}function startDrag(event:DragEvent,id:number){
  if(!editable.value){event.preventDefault();return}
  dragId.value=id
  if(event.dataTransfer){
    event.dataTransfer.effectAllowed='move'
    event.dataTransfer.setData('text/plain',String(id))
  }
}
function allowDrop(event:DragEvent){
  if(!editable.value||!rack.value)return
  event.preventDefault()
  if(event.dataTransfer)event.dataTransfer.dropEffect='move'
}
function dropOn(event:DragEvent,u:number){
  if(!editable.value||!rack.value)return
  event.preventDefault()
  const id=Number(event.dataTransfer?.getData('text/plain')||dragId.value)
  dragId.value=0
  if(Number.isSafeInteger(id)&&id>0)void move(id,Number(rack.value.id),u)
}function place(d:any){const input=document.getElementById('pos-'+d.id) as HTMLInputElement;move(d.id,Number(selectedRack.value),Number(input.value))}function unplace(d:any){move(d.id,null,null)}</script>
